import pymysqlfrom datetime import datetimeimport jsonclass TrackReport:    def __init__(self):        self.conn = pymysql.connect(            host="127.0.0.1",            port=3306,            user="root",            password="你的数据库密码",            database="nonheritage_db",            charset="utf8mb4"        )        self.cursor = self.conn.cursor()    def report(self, event_id, event_name, user_id, culture_id, is_demo=0, ext_info=None):        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")        sql = """        INSERT INTO track_events(event_id,event_name,user_id,culture_id,event_time,is_demo,ext_info)        VALUES(%s,%s,%s,%s,%s,%s,%s)        """        ext = json.dumps(ext_info if ext_info else {})        self.cursor.execute(sql, (event_id,event_name,user_id,culture_id,now,is_demo,ext))        self.conn.commit()if __name__ == "__main__":    tr = TrackReport()    # 模拟上报 e01 用户进入游戏    tr.report("e01","game_enter","u001","cult001",is_demo=1,ext_info={"product":"德庆贡柑"})    print("埋点上报完成")